mapper.select:
/* 권한 그룹 건수 조회 roleManage.selectRoleCount */
SELECT COUNT(1)
FROM TB_ROLE_GRP

/* 권한명 중복 건수 조회 (본인 제외) roleManage.selectRoleNameCount */
SELECT COUNT(1)
FROM TB_ROLE_GRP
WHERE ROLE_NAME = #{roleName}

    AND ROLE_ID != #{roleId}

mapper.insert:
/* 권한 그룹 등록 roleManage.insertRole */
INSERT INTO TB_ROLE_GRP (
    ROLE_ID
    , ROLE_NAME
    , DESCRIPTION
    , USE_YN
    , DEFAULT_YN
    , CREATE_DT
    , CREATE_ID
)
VALUES (
    #{roleId}
    , #{roleName}
    , #{description}
    , #{useYn}
    , #{defaultYn}
    , NOW()
    , #{createId}
)

mapper.update:
/* 권한 그룹 수정 roleManage.updateRole */
UPDATE TB_ROLE_GRP
SET
    ROLE_NAME = #{roleName}
    , DESCRIPTION = #{description}
    , USE_YN = #{useYn}
    , DEFAULT_YN = #{defaultYn}
    , MODIFY_DT = NOW()
    , MODIFY_ID = #{modifyId}
WHERE ROLE_ID = #{roleId}

/* 다른 권한 그룹의 기본 적용 해제 roleManage.resetDefaultRole */
UPDATE TB_ROLE_GRP
SET
    DEFAULT_YN = 'N'
    , MODIFY_DT = NOW()
    , MODIFY_ID = #{modifyId}
WHERE DEFAULT_YN = 'Y'
    AND ROLE_ID != #{roleId}

mapper.delete:
/* 권한 그룹 삭제 roleManage.deleteRole */
DELETE FROM TB_ROLE_GRP
WHERE ROLE_ID = #{roleId}

/* 그룹별 메뉴 권한 삭제 roleManage.deleteRoleMenuByRoleId */
DELETE FROM TB_ROLE_MENU
WHERE ROLE_ID = #{roleId}

mapper.insert:
/* 그룹별 메뉴 권한 등록 (사용 중인 최하위 메뉴만) roleManage.insertRoleMenu */
INSERT INTO TB_ROLE_MENU (
    ROLE_ID
    , MENU_ID
    , READ_YN
    , FUNC_YN
    , CREATE_DT
    , CREATE_ID
)
SELECT
    #{roleId}
    , M.MENU_ID
    , #{readYn}
    , #{funcYn}
    , NOW()
    , #{createId}
FROM TB_MENU M
WHERE M.MENU_ID = #{menuId}
    AND M.IS_LEAF = 'Y'
    AND M.USE_YN = 'Y'

mapper.select:
/* 사용자의 권한 그룹 지정 건수 조회 roleManage.selectUserRoleCount */
SELECT COUNT(1)
FROM TB_USER_ROLE
WHERE USER_ID = #{userId}

mapper.delete:
/* 사용자의 권한 지정 전체 삭제 roleManage.deleteUserRoleByUserId */
DELETE FROM TB_USER_ROLE
WHERE USER_ID = #{userId}

/* 사용자의 특정 권한 그룹 지정 삭제 roleManage.deleteUserRole */
DELETE FROM TB_USER_ROLE
WHERE USER_ID = #{userId}
    AND ROLE_ID = #{roleId}

/* 권한 그룹 소속 사용자 지정 전체 삭제 roleManage.deleteUserRoleByRoleId */
DELETE FROM TB_USER_ROLE
WHERE ROLE_ID = #{roleId}

mapper.insert:
/* 사용자 권한 지정 등록 (존재하는 사용자만) roleManage.insertUserRole */
INSERT INTO TB_USER_ROLE (
    USER_ID
    , ROLE_ID
    , CREATE_DT
    , CREATE_ID
)
SELECT
    U.USER_ID
    , #{roleId}
    , NOW()
    , #{createId}
FROM TB_USER U
WHERE U.USER_ID = #{userId}

/* 한 권한 그룹의 사용자를 다른 그룹으로 복사 지정 (다른 그룹이 있거나 이미 지정된 사용자는 제외) roleManage.insertUserRoleFromRole */
INSERT IGNORE INTO TB_USER_ROLE (
    USER_ID
    , ROLE_ID
    , CREATE_DT
    , CREATE_ID
)
SELECT
    UR.USER_ID
    , #{roleId}
    , NOW()
    , #{createId}
FROM TB_USER_ROLE UR
WHERE UR.ROLE_ID = #{fromRoleId}
    AND NOT EXISTS (
        SELECT 1
        FROM TB_USER_ROLE OT
        WHERE OT.USER_ID = UR.USER_ID
            AND OT.ROLE_ID != #{fromRoleId}
    )
